'use server';

import { runAgent } from "@/lib/agent";

export interface AgentMessage {
  role: 'user' | 'assistant';
  content: string;
}

export async function runAgentAction(
  userMessage: string,
  userId: string,
  chatHistory: AgentMessage[] = [],
  billingContext?: { canUseAgent: () => boolean; incrementAgentUsage: () => void }
): Promise<{ success: boolean; response: string; error?: string; usageLimitReached?: boolean }> {
  try {
    // Check usage limits if billing context is provided
    if (billingContext && !billingContext.canUseAgent()) {
      return {
        success: false,
        response: "",
        error: "You've reached your monthly AI Agent limit. Please upgrade your plan to continue using the AI Agent.",
        usageLimitReached: true,
      };
    }

    const response = await runAgent(userMessage, userId, chatHistory);

    // Increment usage counter if billing context is provided
    if (billingContext) {
      billingContext.incrementAgentUsage();
    }

    return {
      success: true,
      response,
    };
  } catch (error) {
    console.error("Agent error:", error);
    return {
      success: false,
      response: "",
      error: error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
}
